CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN CREATE TYPE user_cefr_level AS ENUM ('Foundation', 'A1', 'A2', 'B1', 'B2'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE mastery_state AS ENUM ('LOCKED','INTRODUCED','LEARNING','PRACTICED','FAMILIAR','FUNCTIONAL','MASTERED','REINFORCING','WEAKENING','REVIEW_REQUIRED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE mistake_severity AS ENUM ('minor','moderate','major','recurring'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS app_profiles (id UUID PRIMARY KEY, display_name VARCHAR(100) NOT NULL DEFAULT 'Learner', target_level user_cefr_level NOT NULL DEFAULT 'B2', verified_level user_cefr_level, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS levels (id TEXT PRIMARY KEY, title TEXT NOT NULL, purpose TEXT NOT NULL, sort_order INT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS units (id TEXT PRIMARY KEY, level_id TEXT NOT NULL REFERENCES levels(id), title TEXT NOT NULL, vocabulary_scope TEXT NOT NULL DEFAULT '', grammar_scope TEXT NOT NULL DEFAULT '', learning_outcome TEXT NOT NULL DEFAULT '', assessment TEXT NOT NULL DEFAULT '', sort_order INT NOT NULL, UNIQUE(level_id, sort_order));
CREATE TABLE IF NOT EXISTS knowledge_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code VARCHAR(80) UNIQUE NOT NULL, title VARCHAR(200) NOT NULL, level user_cefr_level NOT NULL, category VARCHAR(50) NOT NULL, description TEXT NOT NULL DEFAULT '', prerequisites JSONB NOT NULL DEFAULT '[]'::jsonb, unit_id TEXT REFERENCES units(id), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS vocabulary (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), word TEXT NOT NULL, normalized_word TEXT NOT NULL, meaning TEXT NOT NULL, pronunciation TEXT NOT NULL DEFAULT '', part_of_speech TEXT NOT NULL DEFAULT '', example_de TEXT NOT NULL DEFAULT '', example_translation TEXT NOT NULL DEFAULT '', level user_cefr_level NOT NULL, unit_id TEXT REFERENCES units(id), related_words JSONB NOT NULL DEFAULT '[]'::jsonb, source_license TEXT NOT NULL DEFAULT 'original', UNIQUE(normalized_word, level));
CREATE TABLE IF NOT EXISTS grammar_topics (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code TEXT UNIQUE NOT NULL, title TEXT NOT NULL, explanation TEXT NOT NULL DEFAULT '', level user_cefr_level NOT NULL, unit_id TEXT REFERENCES units(id), prerequisites JSONB NOT NULL DEFAULT '[]'::jsonb);
CREATE TABLE IF NOT EXISTS skills (id TEXT PRIMARY KEY, title TEXT NOT NULL, dimension TEXT NOT NULL CHECK (dimension IN ('vocabulary','grammar','pronunciation','reading','listening','writing','speaking','interaction')));
CREATE TABLE IF NOT EXISTS lessons (id TEXT PRIMARY KEY, unit_id TEXT NOT NULL REFERENCES units(id) ON DELETE CASCADE, title TEXT NOT NULL, objective TEXT NOT NULL, content JSONB NOT NULL DEFAULT '{}'::jsonb, sort_order INT NOT NULL, UNIQUE(unit_id, sort_order));
CREATE TABLE IF NOT EXISTS reading_texts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), unit_id TEXT NOT NULL REFERENCES units(id), title TEXT NOT NULL, body TEXT NOT NULL, translation TEXT NOT NULL DEFAULT '', level user_cefr_level NOT NULL, vocabulary JSONB NOT NULL DEFAULT '[]'::jsonb, source_license TEXT NOT NULL DEFAULT 'original');
CREATE TABLE IF NOT EXISTS audio_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), unit_id TEXT NOT NULL REFERENCES units(id), title TEXT NOT NULL, audio_url TEXT, transcript TEXT NOT NULL DEFAULT '', slow_audio_url TEXT, level user_cefr_level NOT NULL, source_license TEXT NOT NULL DEFAULT 'original');
CREATE TABLE IF NOT EXISTS exercises (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), unit_id TEXT NOT NULL REFERENCES units(id), skill TEXT NOT NULL, prompt TEXT NOT NULL, exercise_type TEXT NOT NULL, options JSONB NOT NULL DEFAULT '[]'::jsonb, answer_key JSONB, rubric JSONB NOT NULL DEFAULT '{}'::jsonb, difficulty SMALLINT NOT NULL DEFAULT 1 CHECK (difficulty BETWEEN 1 AND 5), source_license TEXT NOT NULL DEFAULT 'original');
CREATE TABLE IF NOT EXISTS user_progress (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES app_profiles(id) ON DELETE CASCADE, unit_id TEXT NOT NULL REFERENCES units(id), status TEXT NOT NULL DEFAULT 'LOCKED', completion_percent SMALLINT NOT NULL DEFAULT 0 CHECK (completion_percent BETWEEN 0 AND 100), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(user_id, unit_id));
CREATE TABLE IF NOT EXISTS user_knowledge_mastery (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES app_profiles(id) ON DELETE CASCADE, knowledge_item_id UUID NOT NULL REFERENCES knowledge_items(id) ON DELETE CASCADE, mastery_score INT NOT NULL DEFAULT 0 CHECK (mastery_score BETWEEN 0 AND 100), state mastery_state NOT NULL DEFAULT 'LOCKED', last_reviewed TIMESTAMPTZ, next_review TIMESTAMPTZ, interval_days INT NOT NULL DEFAULT 0 CHECK (interval_days >= 0), ease_factor NUMERIC(3,2) NOT NULL DEFAULT 2.50 CHECK (ease_factor >= 1.30), UNIQUE(user_id, knowledge_item_id));
CREATE TABLE IF NOT EXISTS user_vocabulary (user_id UUID NOT NULL REFERENCES app_profiles(id) ON DELETE CASCADE, vocabulary_id UUID NOT NULL REFERENCES vocabulary(id) ON DELETE CASCADE, mastery_score INT NOT NULL DEFAULT 0 CHECK (mastery_score BETWEEN 0 AND 100), next_review TIMESTAMPTZ, interval_days INT NOT NULL DEFAULT 0, ease_factor NUMERIC(3,2) NOT NULL DEFAULT 2.50, last_answer_quality SMALLINT CHECK (last_answer_quality BETWEEN 0 AND 5), PRIMARY KEY(user_id, vocabulary_id));
CREATE TABLE IF NOT EXISTS user_grammar (user_id UUID NOT NULL REFERENCES app_profiles(id) ON DELETE CASCADE, grammar_topic_id UUID NOT NULL REFERENCES grammar_topics(id) ON DELETE CASCADE, mastery_score INT NOT NULL DEFAULT 0 CHECK (mastery_score BETWEEN 0 AND 100), state mastery_state NOT NULL DEFAULT 'LOCKED', updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY(user_id, grammar_topic_id));
CREATE TABLE IF NOT EXISTS user_skills (user_id UUID NOT NULL REFERENCES app_profiles(id) ON DELETE CASCADE, skill_id TEXT NOT NULL REFERENCES skills(id), mastery_score INT NOT NULL DEFAULT 0 CHECK (mastery_score BETWEEN 0 AND 100), assessed_at TIMESTAMPTZ, evidence_count INT NOT NULL DEFAULT 0, PRIMARY KEY(user_id, skill_id));
CREATE TABLE IF NOT EXISTS mistakes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES app_profiles(id) ON DELETE CASCADE, knowledge_item_id UUID REFERENCES knowledge_items(id) ON DELETE SET NULL, exercise_id UUID REFERENCES exercises(id) ON DELETE SET NULL, user_answer TEXT NOT NULL DEFAULT '', expected_answer TEXT NOT NULL DEFAULT '', context TEXT NOT NULL DEFAULT '', severity mistake_severity NOT NULL DEFAULT 'moderate', is_resolved BOOLEAN NOT NULL DEFAULT FALSE, occurrence_count INT NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), resolved_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS review_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES app_profiles(id) ON DELETE CASCADE, knowledge_item_id UUID REFERENCES knowledge_items(id) ON DELETE CASCADE, vocabulary_id UUID REFERENCES vocabulary(id) ON DELETE CASCADE, quality SMALLINT NOT NULL CHECK (quality BETWEEN 0 AND 5), mastery_before SMALLINT NOT NULL DEFAULT 0, mastery_after SMALLINT NOT NULL DEFAULT 0, reviewed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), next_review TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS exams (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code TEXT UNIQUE NOT NULL, title TEXT NOT NULL, level user_cefr_level NOT NULL, exam_type TEXT NOT NULL CHECK (exam_type IN ('lesson','weekly','level','b2_readiness','goethe_prep')), blueprint JSONB NOT NULL DEFAULT '{}'::jsonb, is_published BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS exam_results (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), exam_id UUID NOT NULL REFERENCES exams(id), user_id UUID NOT NULL REFERENCES app_profiles(id) ON DELETE CASCADE, scores JSONB NOT NULL DEFAULT '{}'::jsonb, total_score NUMERIC(5,2), estimated_level user_cefr_level, completed_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS achievements (id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL, criteria JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS user_achievements (user_id UUID NOT NULL REFERENCES app_profiles(id) ON DELETE CASCADE, achievement_id TEXT NOT NULL REFERENCES achievements(id), earned_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY(user_id, achievement_id));
CREATE TABLE IF NOT EXISTS daily_plans (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES app_profiles(id) ON DELETE CASCADE, plan_date DATE NOT NULL DEFAULT CURRENT_DATE, available_minutes SMALLINT NOT NULL CHECK (available_minutes BETWEEN 1 AND 480), tasks JSONB NOT NULL DEFAULT '[]'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(user_id, plan_date));
CREATE TABLE IF NOT EXISTS exercise_attempts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES app_profiles(id) ON DELETE CASCADE, exercise_id UUID NOT NULL REFERENCES exercises(id), answer JSONB NOT NULL DEFAULT '{}'::jsonb, is_correct BOOLEAN, score NUMERIC(5,2), feedback JSONB NOT NULL DEFAULT '{}'::jsonb, attempted_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_mastery_user_review ON user_knowledge_mastery(user_id, next_review);
CREATE INDEX IF NOT EXISTS idx_vocab_user_review ON user_vocabulary(user_id, next_review);
CREATE INDEX IF NOT EXISTS idx_mistakes_user_open ON mistakes(user_id, is_resolved, severity);
CREATE INDEX IF NOT EXISTS idx_attempts_user_date ON exercise_attempts(user_id, attempted_at DESC);
INSERT INTO levels(id,title,purpose,sort_order) VALUES
('Foundation','Foundation','Pre-A1 foundation stage; not an official CEFR level.',0),('A1','A1','Basic familiar expressions and simple interactions.',1),('A2','A2','Routine communication in familiar situations.',2),('B1','B1','Independent communication on familiar topics.',3),('B2','B2','Clear detailed communication and reasoned argument.',4)
ON CONFLICT(id) DO NOTHING;
-- Unit rows are populated from backend/src/data/curriculum_master.json by the seed script at deployment time.
